//
// S06 concept: marks an AI-generated class, method, or property and
// records the verification level applied before acceptance. Apply at the
// smallest granularity that was generated by AI — prefer method-level
// over class-level when only part of a class was generated.

namespace AiToolkit.Infrastructure.AI;

[AttributeUsage(
    AttributeTargets.Class | AttributeTargets.Method | AttributeTargets.Property,
    AllowMultiple = false)]
public sealed class AiGeneratedAttribute(
    VerificationLevel verificationLevel,
    string notes = "") : Attribute {
    public VerificationLevel VerificationLevel { get; } = verificationLevel;

    /// <summary>
    /// Free-text description of what was verified. Visible in code review.
    /// Example: "Verified Channel&lt;T&gt; completion semantics against docs.
    ///           Tested shutdown path explicitly in ShutdownTests.cs."
    /// </summary>
    public string Notes { get; } = notes;
}
